import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize


def unpack(v, n):
    """v: centers (2n) + radii (n). Returns x, y, r."""
    xy = v[:2 * n].reshape(n, 2)
    r = v[2 * n:]
    return xy[:, 0], xy[:, 1], r


def objective(v, n):
    return -np.sum(v[2 * n:])


def constraints(v, n):
    x, y, r = unpack(v, n)
    c = []
    # inside square
    c.append(x - r)
    c.append(1.0 - x - r)
    c.append(y - r)
    c.append(1.0 - y - r)
    # pairwise non-overlap
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            c.append(d - r[i] - r[j])
    return np.concatenate(c)


def pack(start, budget, seed):
    n = 32
    rng = np.random.default_rng(seed)
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
    else:
        s = None

    # Build initial guess: hexagonal-ish layout with modest radii
    if s is None or s.shape != (n, 3):
        s = np.zeros((n, 3))
        cols = 6
        rows = 6
        idx = 0
        for j in range(rows):
            for i in range(cols):
                if idx >= n:
                    break
                x = (i + 0.5 + 0.5 * (j % 2)) / cols
                y = (j + 0.5) / rows
                s[idx] = [min(max(x, 0.05), 0.95), min(max(y, 0.05), 0.95), 0.05]
                idx += 1

    # initial feasible radii shrink
    s[:, 2] = np.minimum.reduce([s[:, 0], 1 - s[:, 0], s[:, 1], 1 - s[:, 1]])
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(s[i, 0] - s[j, 0], s[i, 1] - s[j, 1])
                need = s[i, 2] + s[j, 2]
                if d < need:
                    bad = True
                    over = (need - d) / 2 + 1e-9
                    s[i, 2] = max(s[i, 2] - over, 1e-4)
                    s[j, 2] = max(s[j, 2] - over, 1e-4)
        if not bad:
            break

    best = s.copy()
    best_score = s[:, 2].sum()

    cons = {'type': 'ineq', 'fun': lambda v: constraints(v, n)}
    bounds = [(0, 1)] * (2 * n) + [(1e-5, 0.5)] * n

    t0 = time.process_time()
    deadline = t0 + budget - 0.5
    attempt = 0
    while time.process_time() < deadline:
        attempt += 1
        if attempt == 1:
            v0 = np.concatenate([best[:, :2].ravel(), best[:, 2]])
        else:
            # perturb
            p = best.copy()
            p[:, :2] += rng.normal(0, 0.02, (n, 2))
            p[:, :2] = np.clip(p[:, :2], 0.001, 0.999)
            p[:, 2] *= rng.uniform(0.9, 1.05, n)
            p[:, 2] = np.clip(p[:, 2], 1e-3, 0.5)
            v0 = np.concatenate([p[:, :2].ravel(), p[:, 2]])

        try:
            res = minimize(objective, v0, args=(n,), method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 300, 'ftol': 1e-12})
            v = res.x
        except Exception:
            continue
        x, y, r = unpack(v, n)
        # feasible check
        if np.any(r <= 0):
            continue
        ok = True
        if np.any(x - r < -1e-9) or np.any(1 - x - r < -1e-9) or \
           np.any(y - r < -1e-9) or np.any(1 - y - r < -1e-9):
            ok = False
        if ok:
            for i in range(n):
                for j in range(i + 1, n):
                    d = np.hypot(x[i] - x[j], y[i] - y[j])
                    if d < r[i] + r[j] - 1e-9:
                        ok = False
                        break
                if not ok:
                    break
        if not ok:
            continue
        score = r.sum()
        if score > best_score:
            best = np.column_stack([x, y, r])
            best_score = score

    # final safety shrink
    out = best.copy()
    out[:, 2] *= (1 - 1e-9)
    # ensure inside
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1 - out[:, 2])
    # fix any remaining overlaps conservatively
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                need = out[i, 2] + out[j, 2]
                if d < need + 1e-12:
                    red = (need - d) / 2 + 1e-12
                    out[i, 2] = max(out[i, 2] - red, 1e-6)
                    out[j, 2] = max(out[j, 2] - red, 1e-6)
                    changed = True
        if not changed:
            break
    return out


def construct(budget_seconds, start):
    best = None
    best_score = -1
    seeds = [0, 1, 2]
    t0 = time.process_time()
    per = max((budget_seconds - 0.5) / len(seeds), 0.5)
    for k, sd in enumerate(seeds):
        remaining = budget_seconds - (time.process_time() - t0) - 0.4
        if remaining <= 0.2:
            break
        try:
            res = pack(start if best is None else best, min(per, remaining), sd)
        except Exception:
            continue
        sc = res[:, 2].sum()
        if sc > best_score:
            best_score = sc
            best = res
    if best is None:
        return np.asarray(start, dtype=float) if start is not None else np.zeros((32, 3))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _relax(x, y, r, sweeps=30):
    n = len(r)
    for _ in range(sweeps):
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[j] - x[i]
                dy = y[j] - y[i]
                d2 = dx * dx + dy * dy
                s = r[i] + r[j]
                if d2 < s * s:
                    d = np.sqrt(d2) if d2 > 1e-18 else 1e-9
                    ov = s - d
                    ux = dx / d if d > 1e-12 else 1.0
                    uy = dy / d if d > 1e-12 else 0.0
                    x[i] -= 0.5 * ov * ux
                    y[i] -= 0.5 * ov * uy
                    x[j] += 0.5 * ov * ux
                    y[j] += 0.5 * ov * uy
        for i in range(n):
            if x[i] - r[i] < 0:
                x[i] = r[i]
            if x[i] + r[i] > 1:
                x[i] = 1 - r[i]
            if y[i] - r[i] < 0:
                y[i] = r[i]
            if y[i] + r[i] > 1:
                y[i] = 1 - r[i]
    return x, y


def _max_overlap(x, y, r):
    n = len(r)
    m = 0.0
    for i in range(n):
        m = max(m, r[i] - x[i], r[i] - (1 - x[i]), r[i] - y[i], r[i] - (1 - y[i]))
        for j in range(i + 1, n):
            d = np.hypot(x[j] - x[i], y[j] - y[i])
            m = max(m, r[i] + r[j] - d)
    return m


def _score(x, y, r):
    return float(np.sum(r))


def _active_slsqp(x, y, r, deadline):
    """SLSQP restricted to near-active constraints, with analytic Jacobians."""
    n = len(r)
    v0 = np.concatenate([x, y, r])
    N = 3 * n
    tol = 1e-2

    # Collect near-active constraints
    cons = []
    active_circles = set()

    # pair constraints
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[j] - x[i]
            dy = y[j] - y[i]
            d = np.hypot(dx, dy)
            gap = d - r[i] - r[j]
            if gap < tol:
                if d > 1e-12:
                    ux, uy = dx / d, dy / d
                else:
                    ux, uy = 1.0, 0.0

                def fun(v, i=i, j=j):
                    return np.hypot(v[i] - v[j], v[n + i] - v[n + j]) - v[2 * n + i] - v[2 * n + j]

                def jac(v, i=i, j=j, ux=ux, uy=uy):
                    g = np.zeros(N)
                    g[i] = ux
                    g[n + i] = uy
                    g[j] = -ux
                    g[n + j] = -uy
                    g[2 * n + i] = -1.0
                    g[2 * n + j] = -1.0
                    return g

                cons.append({'type': 'ineq', 'fun': fun, 'jac': jac})
                active_circles.add(i)
                active_circles.add(j)

    # wall constraints
    for i in range(n):
        # left: x - r >= 0
        if x[i] - r[i] < tol:
            def fun(v, i=i):
                return v[i] - v[2 * n + i]
            def jac(v, i=i):
                g = np.zeros(N); g[i] = 1.0; g[2 * n + i] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': fun, 'jac': jac})
            active_circles.add(i)
        # right: 1 - x - r >= 0
        if 1 - x[i] - r[i] < tol:
            def fun(v, i=i):
                return 1 - v[i] - v[2 * n + i]
            def jac(v, i=i):
                g = np.zeros(N); g[i] = -1.0; g[2 * n + i] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': fun, 'jac': jac})
            active_circles.add(i)
        # bottom: y - r >= 0
        if y[i] - r[i] < tol:
            def fun(v, i=i):
                return v[n + i] - v[2 * n + i]
            def jac(v, i=i):
                g = np.zeros(N); g[n + i] = 1.0; g[2 * n + i] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': fun, 'jac': jac})
            active_circles.add(i)
        # top: 1 - y - r >= 0
        if 1 - y[i] - r[i] < tol:
            def fun(v, i=i):
                return 1 - v[n + i] - v[2 * n + i]
            def jac(v, i=i):
                g = np.zeros(N); g[n + i] = -1.0; g[2 * n + i] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': fun, 'jac': jac})
            active_circles.add(i)

    # bounds: freeze circles not in any active constraint
    bounds = []
    for i in range(n):
        if i in active_circles:
            bounds.append((0.0, 1.0))
        else:
            bounds.append((x[i], x[i]))
    for i in range(n):
        if i in active_circles:
            bounds.append((0.0, 1.0))
        else:
            bounds.append((y[i], y[i]))
    for i in range(n):
        if i in active_circles:
            bounds.append((1e-6, 0.5))
        else:
            bounds.append((r[i], r[i]))

    def obj(v):
        return -np.sum(v[2 * n:])

    def obj_jac(v):
        g = np.zeros(N)
        g[2 * n:] = -1.0
        return g

    try:
        res = minimize(obj, v0, jac=obj_jac, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': 1000, 'ftol': 1e-14})
        xr = res.x[:n]
        yr = res.x[n:2 * n]
        rr = res.x[2 * n:]
        return xr, yr, rr
    except Exception:
        return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    rng = np.random.default_rng(12345)

    best_x = best_y = best_r = None
    best_score = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        best_x = s[:, 0].copy()
        best_y = s[:, 1].copy()
        best_r = s[:, 2].copy()
        best_score = _score(best_x, best_y, best_r)

    n = 32
    attempt = 0
    while time.process_time() < deadline:
        attempt += 1
        x = np.zeros(n)
        y = np.zeros(n)
        r = np.full(n, 0.01)
        ok = False
        for _try in range(200):
            x = rng.uniform(0.01, 0.99, n)
            y = rng.uniform(0.01, 0.99, n)
            good = True
            for i in range(n):
                for j in range(i + 1, n):
                    if np.hypot(x[j] - x[i], y[j] - y[i]) < 0.02:
                        good = False
                        break
                if not good:
                    break
            if good:
                ok = True
                break
        if not ok:
            continue

        growth = 1.001
        for step in range(3000):
            if time.process_time() > deadline:
                break
            rn = r * growth
            if np.any(rn > 0.5):
                growth = 1.0 + (growth - 1.0) * 0.5
                continue
            x2, y2 = _relax(x.copy(), y.copy(), rn, sweeps=30)
            ov = _max_overlap(x2, y2, rn)
            if ov > 1e-4:
                growth = 1.0 + (growth - 1.0) * 0.5
                if growth - 1.0 < 1e-9:
                    break
            else:
                x, y, r = x2, y2, rn
                growth = min(growth * 1.0005, 1.01)

        sc = _score(x, y, r)
        if sc > best_score and _max_overlap(x, y, r) < 1e-4:
            best_score = sc
            best_x, best_y, best_r = x.copy(), y.copy(), r.copy()

    if best_x is None:
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        best_x = np.array([p[0] for p in pts])
        best_y = np.array([p[1] for p in pts])
        best_r = np.full(n, 0.02)

    # Active-set SLSQP refinement on the best solution
    if time.process_time() < deadline:
        out = _active_slsqp(best_x, best_y, best_r, deadline)
        if out is not None:
            xr, yr, rr = out
            if _max_overlap(xr, yr, rr) < 1e-7:
                sc = _score(xr, yr, rr)
                if sc > best_score:
                    best_score = sc
                    best_x, best_y, best_r = xr.copy(), yr.copy(), rr.copy()

    best_r = best_r - 1e-9
    best_r = np.maximum(best_r, 1e-8)
    best_x = np.clip(best_x, best_r, 1 - best_r)
    best_y = np.clip(best_y, best_r, 1 - best_r)

    return np.column_stack([best_x, best_y, best_r])
